        $response->assertStatus(200);

        $this->assertDatabaseHas('boards', [
            'id' => $board->id,
            'name' => 'Updated Sample Board',
            'description' => 'Updated board description',
            'board_type' => 'Shareable',
        ]);
    }

    /** @test */
    public function it_checks_input_validation_when_editing_board_details()
    {
        $user = User::factory()->create();
        $workspace = Workspace::factory()->create(['user_id' => $user->id]);
        $board = Board::factory()->create([
            'workspace_id' => $workspace->id,
            'name' => 'Sample Board',
        ]);

        $updatedBoardData = [
            'name' => '',
            'description' => 'Sample board description',
            'board_type' => 'Main',
        ];

        $response = $this->actingAs($user)->putJson("/api/boards/{$board->id}", $updatedBoardData);

        $response->assertStatus(422);
        $response->assertJsonValidationErrors('name');
    }

    /** @test */
    public function it_restricts_editing_boards_for_unauthorized_users()
    {
        $user = User::factory()->create();
        $workspace = Workspace::factory()->create(['user_id' => $user->id]);
        $board = Board::factory()->create([
            'workspace_id' => $workspace->id,
            'name' => 'Sample Board',
        ]);

        $unauthorizedUser = User::factory()->create(); // New unauthorized user

        $updatedBoardData = [
            'name' => 'Updated Sample Board',
            'description' => 'Updated board description',
            'board_type' => 'Shareable',
        ];

        $response = $this->actingAs($unauthorizedUser)->putJson("/api/boards/{$board->id}", $updatedBoardData);

        $response->assertStatus(403); // Forbidden
    }
}
```

